/** debugname -> entry. The stable key: display names are NOT unique (every note shares its base's). */
export const ITEM_BY_NAME: ReadonlyMap<string, ItemValue> =
    new Map(ITEM_VALUES.map(v => [v.debugname, v]));

/** Entry for an obj id, or null for an id outside the table (e.g. an empty inventory slot at -1). */
export function itemValue(id: number): ItemValue | null {
    return ITEM_VALUES[id] ?? null;
}

/** Entry by content name, or null. */
export function itemByName(debugname: string): ItemValue | null {
    return ITEM_BY_NAME.get(debugname) ?? null;
}

/** cost * count for one inventory slot, 0 for an unknown id. The building block of a carried-risk
 *  model: a PvE death drops the WHOLE backpack and worn set (death.rs2 inv_dropall x2). */
export function stackValue(id: number, count: number): number {
    const v = ITEM_VALUES[id];
    return v ? v.cost * count : 0;
}

/** The note of this obj, or the obj itself when it has none. Mirrors OC_CERT exactly. */
export function notedForm(id: number): number {
    const v = ITEM_VALUES[id];
    return v && v.notedId >= 0 ? v.notedId : id;
}
/** The item this note is of, or the obj itself when it is not a note. Mirrors OC_UNCERT exactly. */
export function unnotedForm(id: number): number {
    const v = ITEM_VALUES[id];
    return v && v.unnotedId >= 0 ? v.unnotedId : id;
}

export interface AlchRefusal {
    readonly id: number;
    readonly debugname: string;
    /** 'obj' = its own switch_obj arm, 'category' = oc_category, 'param' = the no_alchemy param */
    readonly kind: 'obj' | 'category' | 'param';
    /** the refusal the server actually prints */
    readonly reason: string;
}

